steps.code:
# Loop: check current song, if not downloaded, go to next song, until we find a downloaded one.
max_steps = len(queue) + 1  # safety
for _ in range(max_steps):
    current = apis.spotify.show_current_song(access_token=access_token)
    if current['song_id'] in downloaded_ids:
        print("Found downloaded song:", current)
        break
    else:
        print(f"Song {current['song_id']} not downloaded, moving to next.")
        apis.spotify.next_song(access_token=access_token)
else:
    print("No downloaded song found in queue.")

