    remaining = matched_set.intersection(current_ids)
    if remaining:
        print(f"Playlist {pl['playlist_id']} ({pl['title']}) still has: {sorted(remaining)}")
        remaining_found = True
    else:
        print(f"Playlist {pl['playlist_id']} ({pl['title']}) clean")

if not remaining_found:
    print("All matched songs removed from original playlists.")

