# Find song IDs for each archive song by searching
archive_song_ids = []
for song in archive_songs:
    query = song['title']
    results = apis.spotify.search_songs(query=query, access_token=spotify_login['access_token'], page_limit=20)
    found = None
    for r in results:
        # Check if any artist matches
        for artist in r['artists']:
            if artist['name'].lower() == song['artist'].lower():
                found = r
                break
        if found:
